#include <stdlib.h>
#include <string.h>
#include <omp.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#else
#define VW 8
#define MR 6
#endif
#define NR (2 * VW)
#define KC 256
#define MC (MR * 8)

typedef float vf __attribute__((vector_size(VW * 4)));
typedef float vfu __attribute__((vector_size(VW * 4), aligned(4), may_alias));

static inline __attribute__((always_inline))
void kern(int kc, const float *restrict a, const float *restrict b,
          float *restrict c, int ldc, int acc)
{
    vf c0[MR], c1[MR];
#pragma GCC unroll 16
    for (int r = 0; r < MR; r++) {
        c0[r] = (vf){0};
        c1[r] = (vf){0};
    }
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float s = a[r];
            c0[r] += b0 * s;
            c1[r] += b1 * s;
        }
        a += MR;
        b += NR;
    }
    if (acc) {
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            vfu *p = (vfu *)(c + (size_t)r * ldc);
            p[0] += c0[r];
            p[1] += c1[r];
        }
    } else {
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            vfu *p = (vfu *)(c + (size_t)r * ldc);
            p[0] = c0[r];
            p[1] = c1[r];
        }
    }
}

static float *bufA, *bufB;
static size_t capA, capB;

static float *ensure(float *buf, size_t *cap, size_t nfl)
{
    size_t bytes = (nfl * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(buf);
        buf = aligned_alloc(64, bytes);
        *cap = bytes;
    }
    return buf;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npA = (n + MR - 1) / MR;
    int npB = (n + NR - 1) / NR;
    bufA = ensure(bufA, &capA, (size_t)npA * MR * n);
    bufB = ensure(bufB, &capB, (size_t)npB * NR * n);
    float *Ap = bufA, *Bp = bufB;

    int nt = omp_get_max_threads();
    int nbi = (n + MC - 1) / MC;
    int ng = (3 * nt + nbi - 1) / nbi;
    if (ng < 1) ng = 1;
    if (ng > npB) ng = npB;
    int ppg = (npB + ng - 1) / ng;
    ng = (npB + ppg - 1) / ppg;
    int nitems = nbi * ng;

#pragma omp parallel
    {
#pragma omp for schedule(static) nowait
        for (int p = 0; p < npA; p++) {
            float *dst = Ap + (size_t)p * MR * n;
            for (int r = 0; r < MR; r++) {
                int i = p * MR + r;
                if (i < n) {
                    const float *src = A + (size_t)i * n;
                    for (int k = 0; k < n; k++)
                        dst[(size_t)k * MR + r] = src[k];
                } else {
                    for (int k = 0; k < n; k++)
                        dst[(size_t)k * MR + r] = 0.0f;
                }
            }
        }

#pragma omp for schedule(static)
        for (int q = 0; q < npB; q++) {
            float *dst = Bp + (size_t)q * NR * n;
            int j0 = q * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < n; k++) {
                memcpy(dst + (size_t)k * NR, B + (size_t)k * n + j0, w * sizeof(float));
                for (int c = w; c < NR; c++)
                    dst[(size_t)k * NR + c] = 0.0f;
            }
        }

        float tmp[MR * NR] __attribute__((aligned(64)));

#pragma omp for schedule(dynamic, 1)
        for (int it = 0; it < nitems; it++) {
            int ib = it / ng, g = it % ng;
            int i0 = ib * MC;
            int mh = n - i0 < MC ? n - i0 : MC;
            int q0 = g * ppg;
            int q1 = q0 + ppg < npB ? q0 + ppg : npB;
            for (int k0 = 0; k0 < n; k0 += KC) {
                int kc = n - k0 < KC ? n - k0 : KC;
                for (int q = q0; q < q1; q++) {
                    int j0 = q * NR;
                    int w = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + (size_t)q * NR * n + (size_t)k0 * NR;
                    for (int ii = 0; ii < mh; ii += MR) {
                        int p = (i0 + ii) / MR;
                        int h = n - i0 - ii < MR ? n - i0 - ii : MR;
                        const float *ap = Ap + (size_t)p * MR * n + (size_t)k0 * MR;
                        float *cp = C + (size_t)(i0 + ii) * n + j0;
                        if (h == MR && w == NR) {
                            kern(kc, ap, bp, cp, n, k0 > 0);
                        } else {
                            kern(kc, ap, bp, tmp, NR, 0);
                            for (int r = 0; r < h; r++)
                                for (int c = 0; c < w; c++) {
                                    float v = tmp[r * NR + c];
                                    if (k0) v += cp[(size_t)r * n + c];
                                    cp[(size_t)r * n + c] = v;
                                }
                        }
                    }
                }
            }
        }
    }
}
